// المستودع يمتلك نطاق التطبيق ويدير WorkManager:
@Singleton
class OrderRepository @Inject constructor(
    private val orderDao: OrderDao,
    private val workManager: WorkManager,
    @ApplicationScope private val appScope: CoroutineScope
) {
    suspend fun submitOrder(order: Order) {
        // 1. حفظ محلي سريع ومضمون داخل نطاق التطبيق (لا يقطعه موت الشاشة):
        appScope.launch {
            orderDao.insert(order.copy(status = SyncStatus.PENDING))

            // 2. تفويض الرفع للسيرفر لـ WorkManager لضمان البقاء بعد موت التطبيق بالكامل:
            val request = OneTimeWorkRequestBuilder<OrderSyncWorker>()
                .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
                .setInputData(workDataOf("order_id" to order.id))
                .build()
            workManager.enqueueUniqueWork("sync_${order.id}", ExistingWorkPolicy.KEEP, request)
        }.join()
    }
}
```

